def cari_rentang_target(nums: list[int], target: int) -> tuple[int, int]:
    """
    Mencari indeks awal dan indeks akhir kemunculan target pada daftar terurut menaik.

    Args:
        nums: Daftar bilangan bulat yang terurut menaik.
        target: Nilai yang akan dicari rentang kemunculannya.

    Returns:
        Tuple (indeks_awal, indeks_akhir) yang bersifat berbasis 0 dan inklusif.
        - Jika nums kosong atau target tidak ditemukan, kembalikan (-1, -1).
        - Jika target hanya muncul satu kali, kembalikan (k, k) dengan k sebagai indeks kemunculannya.
    """
    if not nums:
        return (-1, -1)

    n = len(nums)

    def cari_indeks_awal() -> int:
        """Mencari indeks pertama di mana nums[i] >= target."""
        lo, hi = 0, n - 1
        result = n  # Jika tidak ditemukan, kembalikan n (di luar rentang)
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] >= target:
                result = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return result

    def cari_indeks_akhir() -> int:
        """Mencari indeks terakhir di mana nums[i] <= target."""
        lo, hi = 0, n - 1
        result = -1  # Jika tidak ditemukan, kembalikan -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] <= target:
                result = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return result

    awal = cari_indeks_awal()
    akhir = cari_indeks_akhir()

    # Validasi: pastikan awal dan akhir valid dan mengarah ke target
    if awal != n and akhir != -1 and nums[awal] == target and nums[akhir] == target:
        return (awal, akhir)
    else:
        return (-1, -1)
